import json


def append_agent_guide(doc, root, add_table, add_code_block):
    path = root / 'reports/agent_validation.json'
    if not path.exists():
        return
    report = json.loads(path.read_text(encoding='utf-8'))
    doc.add_page_break()
    doc.add_heading('Агент помощник оператора поддержки', level=1)
    doc.add_paragraph('Следующий этап проекта — агент, который выбирает разрешённые инструменты по ситуации. Он может найти статью и подготовить цитируемый ответ, запросить детали или составить черновик передачи человеку. Это расширение уже проверенного API. Агент не выполняет переводы, возвраты и блокировки, не отправляет тикеты и сообщения: его инструменты ограничены чтением и подготовкой результата для оператора.')
    doc.add_heading('Почему здесь нужен агент', level=2)
    doc.add_paragraph('Обычный pipeline всегда исполняет заранее заданную последовательность. Агент выбирает следующий шаг по исходному вопросу и результатам предыдущих действий. Например, конкретный вопрос требует поиска, неясное обращение — уточнения, а явная просьба позвать человека — подготовки передачи. Термин «агент» имеет смысл, когда выбор действия действительно делегирован модели и проверяется экспериментально.')
    doc.add_paragraph('Выбрана небольшая явная реализация цикла и policy-state на Python. Для пяти инструментов она позволяет изучить весь контрольный поток без дополнительного framework. LangGraph мог бы помочь при устойчивых checkpoints, длительных задачах и сложных переходах, но в этой версии он не используется. На собеседовании нужно называть реализованные технологии точно: JSON planner через Ollama, серверный allowlist, проверка состояния и ограниченный цикл, а не утверждать, что здесь построена система на LangGraph.')
    doc.add_heading('Разрешённые инструменты и их полномочия', level=2)
    add_table(doc, ['Инструмент', 'Назначение', 'Контроль сервера'], [
        ('classify_inquiry', 'Предварительная категория английского банковского обращения', 'Только английский BANKING77; метка не означает подтверждённую срочность'),
        ('search_knowledge', 'Найти статьи для исходного вопроса', 'Текст и язык задаются сервером; LLM не может подменить вопрос или источник'),
        ('prepare_answer', 'Собрать точные выдержки с источниками', 'Разрешён только после threshold_passed; сервер повторно проверяет цитаты'),
        ('draft_ticket', 'Подготовить данные для оператора', 'draft_only, submitted=false; никаких внешних вызовов отправки'),
        ('ask_clarification', 'Уточнить недостающие сведения', 'Проверенный статический текст на выбранном языке; запрос завершается')])
    doc.add_paragraph('Существующий серверный поиск использует откалиброванный lexical retriever. Dense/RRF остаются отдельным экспериментом: для их score ещё не подготовлены пороги отказа. Это важно, потому что агент не должен обходить ограничения базы знаний только за счёт способности красиво сформулировать ответ.')
    doc.add_heading('Что выбирает модель и что решает код', level=2)
    doc.add_paragraph('Planner получает вопрос, язык, выполненные инструменты, компактные наблюдения и оставшийся бюджет. Ответ модели содержит только поле tool из разрешённого enum. Здесь используется structured JSON decision через /api/chat, а не нативный массив tool_calls Ollama. Исполнитель функций написан приложением. В этой версии аргументы инструментов фиксированы сервером; свободное создание query, URL, SQL или shell-команд моделью не допускается.')
    add_code_block(doc, '''{"tool": "search_knowledge"}
{"tool": "prepare_answer"}''')
    doc.add_paragraph('Набор доступных действий зависит от состояния. До поиска нельзя вызывать prepare_answer. После успешного поиска доступен ответ, после неподдержанного результата — уточнение или передача. Уже выполненные инструменты исключаются из JSON schema следующего шага и дополнительно проверяются сервером. Это пример того, почему одну фразу в prompt нельзя считать достаточным ограничением полномочий.')
    doc.add_paragraph('Источник и текст цитаты не принимаются от планировщика. prepare_answer использует имеющуюся выдачу, а исполнитель проверяет chunk_id, document_id, source и точную подстроку quote. Сам текст ответа собирается сервером из этих цитат. Так проверяется происхождение текста, но не доказывается предметная релевантность статьи: ошибка retrieval всё ещё может привести к нерелевантной выдержке.')
    doc.add_heading('Граф переходов и бюджет', level=2)
    add_table(doc, ['Состояние', 'Доступные действия', 'Терминальный результат'], [
        ('Новый вопрос', 'Поиск, уточнение, черновик; классификация опциональна для en', 'clarification_required или handoff'),
        ('Поиск threshold_passed', 'prepare_answer, уточнение или черновик', 'answered с цитатами'),
        ('Поиск без поддержки', 'Уточнение или черновик', 'clarification_required или handoff'),
        ('Ошибка или исчерпанный бюджет', 'Серверная передача без нового LLM-вызова', 'handoff с reason')])
    doc.add_paragraph('По умолчанию максимум четыре шага, жёсткий серверный предел — шесть. Каждый шаг вызывает planner не более одного раза. Внешний запрос к Ollama имеет timeout до 25 секунд и ограничение размера ответа. Общий deadline — 60 секунд с кооперативной проверкой на границах операций: это не принудительное прерывание любого Python callback. Два слота BoundedSemaphore ограничивают параллельные agent-запросы одного процесса; переполнение возвращает HTTP 429. При нескольких workers лимит нужно координировать централизованно.')
    doc.add_paragraph('Запросы stateless: состояние существует только внутри одного вызова /v1/agent/run. Если агент попросил детали, клиент отправляет новый полный вопрос с уточнением. Долговременная память, диалоги и фоновые задания пока не реализованы. Trace содержит инструмент, результат и длительность шага вместе с выбором модели; внутренние рассуждения модели не сохраняются и не выдаются.')
    doc.add_paragraph('Для обращений, состоящих только из общих слов вроде «Помогите, ничего не работает» или Please help me, действует прозрачный лексический guard: сначала запросить компонент, шаги и текст ошибки. Он не вызывает LLM и отмечается required_by_policy в trace. Это ограниченная эвристика для общих фраз на двух языках, а не полноценная модель семантической неоднозначности.')
    doc.add_heading('Что показал первый реальный прогон', level=2)
    doc.add_paragraph('Первая версия на Qwen2.5 0.5B проходила детерминированные тесты, но реальный LLM повторял search_knowledge вместо перехода к prepare_answer. Сервер блокировал цикл и формировал черновик. Это безопасное поведение, но вопрос пользователя оставался нерешённым. Пример показывает различие между корректным executor и качественным planner.')
    doc.add_paragraph('Дополнительно обнаружен дефект оценки: совпадение финального статуса handoff ошибочно засчитывало некоторые аварийные передачи как успешный выбор оператора. Методика усилена: для явной передачи требуется реальный draft_ticket в trace, для ответа — ожидаемый источник, а loop/timeout/provider failure не считаются решением задачи. Начальный отчёт сохранён в reports/agent_pilot.json с предупреждением о слабой status-only метрике.')
    doc.add_paragraph('После пилота набор действий ограничен динамической schema и серверным состоянием. Для planner проверяется Qwen2.5 1.5B отдельно от модели 0.5B, ранее применявшейся к выбору цитат. Сценарии разработки используются для отладки и не являются независимым holdout, поэтому улучшение на них нельзя представлять как обобщающую оценку agent intelligence.')
    doc.add_paragraph('Промежуточный прогон 1.5B решил 4 из 5 задач, но выдал цитату на неясное «ничего не работает»: lexical retrieval нашёл знакомые слова и пропустил порог. Эта ошибка сохранена в reports/agent_development.json. После неё добавлен guard общих фраз и отдельные тесты на другие английские и русские формулировки. Это исправление по development-кейсу, поэтому итоговые результаты остаются отладочной проверкой, а не независимым benchmark.')
    doc.add_heading('Результаты текущей проверки', level=2)
    doc.add_paragraph(f"Реальные HTTP-вызовы planner: модель {report['model']}. Правильно решённых сценариев: {report['passed']}/{report['total']}. Проверка разрешённых действий: {report.get('safety_passed', 'нет данных')}/{report.get('safety_total', 'нет данных')}. Это небольшой автоматически составленный набор о демонстрационном приложении, а не экспертная оценка банковской поддержки.")
    doc.add_paragraph(f"Автоматические проверки: {report.get('automated_tests', {}).get('tests_run', 'нет данных')} тестов, включая executor, API, budgets, неизвестные инструменты, неподдержанные состояния retrieval и проверку цитат. Общий notebook агента выполнен в Jupyter. Фактический digest planner: {report.get('model_digest', 'не зафиксирован')}.")
    add_table(doc, ['Сценарий', 'Ожидание', 'Фактически', 'Инструменты', 'Секунды'], [
        (row['case_id'], row['expected'], str(row['actual']), ' → '.join(row['tools']), f"{row['latency_seconds']:.2f}")
        for row in report['cases']])
    doc.add_paragraph('Проверка безопасности здесь имеет узкий смысл: не вызван инструмент за пределами allowlist и не отправлен тикет. Это не доказательство устойчивости ко всем prompt injections. Отдельно нужны разнообразные атаки на источники, многократные прогоны, корректность уточнений и экспертная оценка выбранного действия. HTTP 200 само по себе не означает успешную задачу.')
    doc.add_heading('Как запустить и изучить', level=2)
    doc.add_paragraph('Сервер: src/agent/service.py и POST /v1/agent/run в src/api/main.py. Сценарии: scripts/verify_agent_http.py. Ноутбук: notebooks/08_operator_agent.ipynb. В Compose для планировщика задан AGENT_MODEL; для прежнего quote selector оставлен OLLAMA_MODEL. При недоступной модели агент выдаёт контролируемый handoff с причиной, а не выдумывает результат инструмента.')
    add_code_block(doc, '''$env:SUPPORT_API_KEY = 'replace-with-your-secret'
docker compose -f compose.yaml -f compose.llm.yaml up --build -d --wait
docker compose -f compose.yaml -f compose.llm.yaml exec ollama ollama pull qwen2.5:1.5b
python scripts/verify_agent_http.py
docker compose -f compose.yaml -f compose.llm.yaml down''')
    doc.add_page_break()
    doc.add_heading('Пример запроса к агенту', level=2)
    add_code_block(doc, '''POST /v1/agent/run
x-api-key: your-secret
{
  "text": "Как установить зависимости проекта?",
  "language": "ru",
  "max_steps": 4
}''')
    doc.add_heading('Вопросы для собеседования об агенте', level=2)
    for question, answer in [
        ('Чем агент отличается от фиксированного pipeline', 'В pipeline порядок действий определён кодом заранее. Здесь модель выбирает следующий разрешённый инструмент по наблюдениям. При этом полномочия, допустимые переходы и исполнение остаются под контролем сервера.'),
        ('Почему недостаточно prompt не вызывай опасные инструменты', 'Модель может ошибиться или последовать тексту источника. Серверный allowlist и валидация состояния не позволяют исполнить действие, которого нет в приложении, независимо от содержимого prompt.'),
        ('Что такое tool selection accuracy', 'Это правильность выбора действия в размеченном состоянии. Для нашего draft_ticket важно не только получить финальный handoff, но и действительно выбрать инструмент передачи, а не упасть в аварийный fallback. Полный task success дополнительно требует правильного источника и ответа.'),
        ('Почему маленькая модель подходит для цитат но может не подходить агенту', 'Выбор точной цитаты в узкой schema проще многошагового планирования. Planner должен учитывать историю инструментов, условие остановки и результат поиска. Поэтому успех старого quote selector нельзя автоматически переносить на новую задачу.'),
        ('Как ограничить стоимость и зацикливание', 'Ограничить число шагов, timeout провайдера, размер контекста, повторные действия и параллельные запросы. Дополнительно наблюдать число planner calls, task success, аварийные передачи и latency. Безопасный fallback важен, но его частоту нельзя скрывать в успешных статусах.'),
        ('Почему не добавили реальные банковские действия', 'Для них требуются подтверждённые полномочия, авторизация пользователя, идемпотентность, аудит, обратимость и отдельная приёмка. Учебный агент пока только читает знания и готовит черновики; никаких транзакций его инструменты не выполняют.')]:
        doc.add_heading(question, level=3)
        doc.add_paragraph(answer)
    doc.add_paragraph('Первичный источник протокола: https://docs.ollama.com/capabilities/tool-calling. В проекте намеренно реализован отдельный constrained JSON planner, а не заявлена поддержка нативных tool_calls без соответствующей реализации.')
